function answerFrame(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore,
  validation: ValidationResult,
  history?: {enabled: boolean}
): void | Promise<void> {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') return handlePing(ws, message.timestamp);
  if (message.type === 'list_sessions') return handleListSessions(ws, session, sessionStore, message, history);
}

async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore,
  message: import('../../types/messages.js').ListSessionsMessage,
  history?: {enabled: boolean}
): Promise<void> {
  if (!history?.enabled) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'History listing is not enabled');
    return;
  }

  if (!sessionStore.listFor) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'Store does not support listing conversations');
    return;
  }

  try {
    const userId = (ws as ExtWebSocket).userId ?? session.userId;
    const {limit, before} = message;
    const summaries = await sessionStore.listFor(userId, {limit, before});
    sendSessionList(
      ws,
      summaries.map(s => ({
        sessionId: s.sessionId,
        createdAt: s.createdAt.toISOString(),
        updatedAt: s.updatedAt.toISOString(),
        entryCount: s.entryCount,
      }))
    );
  } catch (error) {
    if (error instanceof StoreCannotList) {
      sendError(ws, ErrorCodes.UNSUPPORTED, error.message);
      return;
    }
    throw error;
  }
}

